parameters.jsCode:
const raw = $input.first()?.json?.output || '';
let message = '';
try {
  const m = raw.match(/\{[\s\S]*\}/);
  message = m ? JSON.parse(m[0]).message : raw;
} catch (e) {
  message = raw;
}
return [{ json: { message: message || '', status: message ? 'ok' : 'fallback_needed' } }];
